        You will be given the root cause of a bug, the commit message and the corresponding patch.
        You need to extract all code statements that lead to the bug from the patch, based on the root cause and the commit message.

        Root cause:
        The root cause of the bug was the introduction of stricter const qualifiers for read-only data in a previous changeset, which led to a warning about discarded qualifiers when the `__transferBytes` function was called with non-const data. This warning occurred because the function was not correctly indicating that the input data was read-only, resulting in potential misuse of the data and compiler warnings when compiling with all warnings enabled.

        Commit message:
        SPI: Fix discarded-qalifiers warning when compiling with all
 warnings (#3458)

* SPI: Fix discarded-qalifiers warning when compiling with all warnings

This fixes an error introduced with changeset b847f41 which
tightened the use of const for read-only data. The helper
funtion __transferBytes also requires the const qualifier on
outgoing data. Without this change a warning is displayed
when compiling with the Arduino IDE set to display "All"
compiler warnings.

Tests:
 - Build an ESP32 SPI sketch that uses static const data to send
   to an SPI device using the SPI.transferBytes() API

* SPI:Ensure all local functions are marked static

This audits all functions in the esp32-hal-xpi.c module and
ensures that any functions entirely local to the module are
marked as static.

Tests:
 - Build with Arduino set to show all warnings and ensure none
   are displayed

* SPI: Remove unused local __spiTranslate24 function

This removes the __spiTranslate24() function which is unused.  

        Patch:

-uint32_t __spiTranslate24(uint32_t data)
-{
-    union {
-        uint32_t l;
-        uint8_t b[4];
-    } out;
-    out.l = data;
-    return out.b[2] | (out.b[1] << 8) | (out.b[0] << 16);
-}
-
-uint32_t __spiTranslate32(uint32_t data)
+static uint32_t __spiTranslate32(uint32_t data)
 {
     union {
         uint32_t l;
         uint8_t b[4];
     } out;
     out.l = data;
     return out.b[3] | (out.b[2] << 8) | (out.b[1] << 16) | (out.b[0] << 24);
 }


-void __spiTransferBytes(spi_t * spi, uint8_t * data, uint8_t * out, uint32_t bytes)
+static void __spiTransferBytes(spi_t * spi, const uint8_t * data, uint8_t * out, uint32_t bytes)
 {
     if(!spi) {
         return;
     }
     int i;

     if(bytes > 64) {
         bytes = 64;
     }

     uint32_t words = (bytes + 3) / 4;//16 max

     uint32_t wordsBuf[16] = {0,};
     uint8_t * bytesBuf = (uint8_t *) wordsBuf;

     if(data) {
         memcpy(bytesBuf, data, bytes);//copy data to buffer
     } else {
         memset(bytesBuf, 0xFF, bytes);
     }

     spi->dev->mosi_dlen.usr_mosi_dbitlen = ((bytes * 8) - 1);
     spi->dev->miso_dlen.usr_miso_dbitlen = ((bytes * 8) - 1);

     for(i=0; i<words; i++) {
         spi->dev->data_buf[i] = wordsBuf[i];    //copy buffer to spi fifo
     }

     spi->dev->cmd.usr = 1;

     while(spi->dev->cmd.usr);

     if(out) {
         for(i=0; i<words; i++) {
             wordsBuf[i] = spi->dev->data_buf[i];//copy spi fifo to buffer
         }
         memcpy(out, bytesBuf, bytes);//copy buffer to output
     }
 }



